import { RPECandidateRef } from '../rpe-candidate/index.js';
import { 
  RPECandidateGeneratorCandidate,
} from '../rpe-candidate-generator/index.js';

/**
 * A candidate generated by the RPE candidate generator.
 * @category Reflective Prompt Evolution
 * @see {@link toCandidateGeneratorOutputCandidate}
 */
export type CandidateGeneratorOutputCandidate =
  Omit<RPECandidateGeneratorCandidate, 'candidate'> &
{
  /**
   * Reference to the candidate.
   */
  candidateRef: RPECandidateRef;
};

/**
 * Output for the RPE candidate generator.
 * @category Reflective Prompt Evolution
 */
export interface CandidateGeneratorOutput {
  /**
   * New candidates.
   */
  candidates: CandidateGeneratorOutputCandidate[];
}